function getCodeWhispererTranslation(key, lang) {
    if (codewhispererTranslations[lang] && codewhispererTranslations[lang][key]) {
        return codewhispererTranslations[lang][key];
    }
    if (codewhispererTranslations.en && codewhispererTranslations.en[key]) {
        return codewhispererTranslations.en[key];
    }
    return null;
}

function applyCodeWhispererTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && (key.startsWith('review.codewhisperer.') || key.startsWith('review.common.') || key.startsWith('nav.'))) {
            const translation = getCodeWhispererTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyCodeWhispererTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyCodeWhispererTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyCodeWhispererTranslations(currentLang);
}


